/**
 * LocaleInterface describes the allowed locales, with its properties.
 * It is an interface instead of a type so that each site can extend what locales they support.
 */
// eslint-disable-next-line @typescript-eslint/consistent-type-definitions, @typescript-eslint/no-empty-interface
export interface LocaleInterface extends Record<"en" | "sv", unknown> {}

export type Locale = keyof LocaleInterface;

export type ILanguage = {
  locale: Locale;
  default: boolean;
};

class LanguageHelper {
  currentLocale: Locale;
  locales: Array<ILanguage>;

  constructor() {
    this.currentLocale = "sv";
    this.locales = [];
  }

  setLocale(locale: Locale) {
    this.currentLocale = locale;
  }

  getCurrentLocale(): Locale {
    return this.currentLocale;
  }

  setAvailableLanguages(locales: Array<ILanguage>) {
    this.locales = locales;
  }

  getAllLanguages() {
    return this.locales;
  }
}

const helper = new LanguageHelper();
export default helper;
