// @ts-strict-ignore
import dayjs, { ManipulateType, OpUnitType, QUnitType } from "dayjs";
import "dayjs/locale/sv";

import customParseFormat from "dayjs/plugin/customParseFormat";
import isBetween from "dayjs/plugin/isBetween";
import updateLocale from "dayjs/plugin/updateLocale";
import timezone from "dayjs/plugin/timezone";
import utc from "dayjs/plugin/utc";
import duration from "dayjs/plugin/duration";
import { parseInt } from "lodash-es";
import LanguageHelper from "./language-helper";
import { TodayHelper } from "./today-helper";
import { Translation } from "@/core/labels/i18n";

dayjs.extend(isBetween);
dayjs.extend(updateLocale);
dayjs.extend(customParseFormat);
dayjs.extend(timezone);
dayjs.extend(utc);
dayjs.extend(duration);

dayjs.updateLocale("en", {
  months: [
    "januari",
    "februari",
    "mars",
    "april",
    "maj",
    "juni",
    "juli",
    "augusti",
    "september",
    "oktober",
    "november",
    "december",
  ],
});

export type DateSource = Parameters<typeof dayjs>[0];
export type DateString = `${number}-${number}-${number}` | "";

export class DateSet extends Set<DateString> {
  constructor(values?: Iterable<DateString> | Iterable<Date> | null) {
    super(values && helper.toDateStrings(values));
  }
  has(key: Date | DateString) {
    if (key instanceof Date) key = helper.toStringYYYYMMDD(key);
    return super.has(key);
  }
}

export class DateMap<T> extends Map<DateString, T> {
  has(key: Date | DateString) {
    if (key instanceof Date) key = helper.toStringYYYYMMDD(key);
    return super.has(key);
  }
  get(key: Date | DateString) {
    if (key instanceof Date) key = helper.toStringYYYYMMDD(key);
    return super.get(key);
  }
  set(key: Date | DateString, value: T) {
    if (key instanceof Date) key = helper.toStringYYYYMMDD(key);
    return super.set(key, value);
  }
}

class DateHelper {
  toStringYYYYMMDD(date: DateSource): DateString {
    if (!date) {
      return "";
    }

    return dayjs(date).format("YYYY-MM-DD") as DateString;
  }

  toDateStrings(dates: Iterable<DateSource>): Array<DateString> {
    return [...dates].map((d) => this.toStringYYYYMMDD(d));
  }

  toStringDDMMYYYY(date: DateSource): string {
    if (!date) {
      return "";
    }

    return dayjs(date).format("DD-MM-YYYY");
  }

  getEndOfYearDate(): Date {
    return dayjs(TodayHelper.getNow()).endOf("year").toDate();
  }

  getStartOfYearDate(): Date {
    return dayjs(TodayHelper.getNow()).startOf("year").toDate();
  }

  addDays(date: DateSource, days: number): Date {
    const result = createDate(date);
    result.setDate(result.getDate() + days);
    return result;
  }

  getModifiedDateByMonth(date: DateSource, monthChange: number): Date {
    const newDate = createDate(date);
    newDate.setDate(1);

    if (monthChange === -1) {
      newDate.setDate(0);
    } else {
      newDate.setMonth(newDate.getMonth() + monthChange);
    }
    return newDate;
  }

  toStringTimeHHMM(date: DateSource): string {
    if (!date) {
      return "";
    }
    return dayjs(date).format("HH:mm");
  }

  toStringNonLocalTimeHHMM(date: DateSource): string {
    if (!date || !dayjs(date).isValid()) {
      return "";
    }
    return dayjs(date).format("HH:mm");
  }

  /** Will convert amount of seconds to a string like "3 minutes 14 seconds"*/
  toStringTimeMinutesAndSeconds(t: Translation, seconds: number): string {
    const minutes = Math.floor(seconds / 60);
    const remainingSeconds = seconds % 60;
    if (minutes > 0) {
      return t("minutesAndSeconds", { minutes, seconds: remainingSeconds });
    }
    return t("seconds", { seconds: remainingSeconds });
  }

  toStringTimeYYYYMMDDHHMM(date: DateSource): string {
    if (!date || !dayjs(date).isValid()) {
      return "";
    }
    return dayjs(date).format("YYYY-MM-DDTHH:mm");
  }

  toStringMMMYYYY(date: DateSource) {
    return dayjs(date).format("MMM YYYY");
  }

  toStringDD(date: DateSource) {
    return dayjs(date).toDate().toLocaleDateString(LanguageHelper.currentLocale, {
      weekday: "short",
    });
  }

  /**
   *
   * @param {DateSource} date
   * @returns {string} Date formatted month date and weekday - for sv it is "tisdag 28 maj"
   */
  toStringMMDDWeekday(date: DateSource): string {
    if (!date) {
      return "";
    }

    return dayjs(date)
      .toDate()
      .toLocaleDateString(LanguageHelper.currentLocale, { month: "long", day: "numeric", weekday: "long" });
  }

  /**
   *
   * @param {DateSource} date
   * @returns {string} Date formatted weekday comma month dat - for sv it is "tisdag, apr 23"
   */
  toStringWeekdayMMDD(date: DateSource): string {
    if (!date) {
      return "";
    }
    return dayjs(date).locale(LanguageHelper.currentLocale).format("dddd, MMM D");
  }

  /**
   *
   * @param {DateSource} date
   * @returns {string} Date formatted month date and weekday with year - for sv it is "tisdag 28 maj 2022"
   */
  toStringWeekdayDDMonthYear(date: DateSource) {
    if (!date) {
      return "";
    }

    return dayjs(date).toDate().toLocaleDateString(LanguageHelper.currentLocale, {
      weekday: "long",
      year: "numeric",
      month: "long",
      day: "numeric",
    });
  }

  /**
   * @param {DateSource} date
   * @returns {String} Date as string with format {DD  Month} and localisation of locale settings
   */
  toStringDDMonth(date: DateSource): string {
    if (!date) {
      return "";
    }

    return dayjs(date).toDate().toLocaleDateString(LanguageHelper.currentLocale, { day: "numeric", month: "long" });
  }

  /**
   * @param {DateSource} date
   * @returns {String} Date as string with format {DD  Month} and localisation of locale settings
   */
  toStringDDShortMonth(date: DateSource) {
    if (!date) {
      return "";
    }

    return dayjs(date).toDate().toLocaleDateString(LanguageHelper.currentLocale, { day: "numeric", month: "short" });
  }

  /**
   * @param {DateSource} date
   * @returns {String} Date as string with format {DD  Month} and localisation of locale settings
   */
  toStringDDMonthYear(date: DateSource) {
    if (!date) {
      return "";
    }

    return dayjs(date)
      .toDate()
      .toLocaleDateString(LanguageHelper.currentLocale, { day: "numeric", month: "short", year: "numeric" });
  }

  /**
   * @param {Date} date
   * @returns {String} Time from date as string formatted with HH:MM and localisation of browser settings. Ex: 14 januari 14:35
   */
  toStringDDMMHHMM(date: Date) {
    if (!(date instanceof Date)) {
      return "";
    }

    return date.toLocaleTimeString(LanguageHelper.currentLocale, {
      day: "numeric",
      month: "long",
      hour: "2-digit",
      minute: "2-digit",
    });
  }

  hasDatePassed(date: DateSource, offset = 0, offsetUnit: ManipulateType = null): boolean {
    const dateToCheck = offset > 0 && offsetUnit ? dayjs(date).add(offset, offsetUnit) : dayjs(date);
    return dayjs(TodayHelper.getNow()).isAfter(dateToCheck, offsetUnit);
  }

  hasTimePassedToday(time: string): boolean {
    const now = dayjs(TodayHelper.getNow());

    const [hour, minute] = time.split(":");
    const hourNumber = parseInt(hour, 10);
    const minuteNumber = parseInt(minute, 10);
    const eventTime = dayjs(TodayHelper.getNow()).hour(hourNumber).minute(minuteNumber);
    return now.isAfter(eventTime);
  }

  /**
   * @param {DateSource} date
   * @param {number} offsetInMinutes offset in minutes, use as grace period
   * @returns {Boolean} returns true if date is passed, optional offset provided
   */

  isDatePassed(date: DateSource, offsetInMinutes = 0) {
    const dateWithOffset = createDate(date);
    dateWithOffset.setMinutes(dateWithOffset.getMinutes() + offsetInMinutes);
    return dateWithOffset < createDate();
  }

  millisecondsUntilDate(date: DateSource): number {
    return dayjs(date).diff(dayjs(TodayHelper.getNow()), "ms");
  }

  minutesPassedSinceDate(date: DateSource): number {
    return dayjs(TodayHelper.getNow()).diff(dayjs(date), "minutes");
  }

  minutesBeforeDate(date: DateSource): number {
    return dayjs(date).diff(dayjs(TodayHelper.getNow()), "minutes");
  }

  isEqualLocaleDateStringYYYYMMDD(date1, date2) {
    if (this.isDateValid(date1) && this.isDateValid(date2)) {
      return (
        date1.toLocaleDateString(LanguageHelper.currentLocale) ===
        date2.toLocaleDateString(LanguageHelper.currentLocale)
      );
    }
    return false;
  }

  isEqualYYYYMMDDHHMM(date1: DateSource, date2: DateSource) {
    return dayjs(date1).isSame(dayjs(date2), "minute");
  }

  isTodayInDateSpan(dateFrom: DateSource, dateTo: DateSource): boolean {
    return dayjs(TodayHelper.getNow()).isBetween(dayjs(dateFrom), dayjs(dateTo), "day", "[]");
  }

  isDateInDateSpan(
    date: DateSource,
    dateSpanFrom: DateSource,
    dateSpanTo: DateSource,
    granularity: OpUnitType = "second",
  ): boolean {
    return dayjs(date).isBetween(dayjs(dateSpanFrom), dayjs(dateSpanTo), granularity, "[]");
  }

  isToday(date: DateSource): boolean {
    return this.isEqualYYYYMMDD(date, dayjs(TodayHelper.getNow()));
  }

  isEqualYYYYMMDD(date1: DateSource, date2: DateSource): boolean {
    return dayjs(date1).isSame(dayjs(date2), "date");
  }

  isEqualYYYYMM(date1: DateSource, date2: DateSource): boolean {
    return dayjs(date1).isSame(dayjs(date2), "month");
  }

  isLessThanYYYYMM(date1: Date, date2: Date): boolean {
    if (date1 instanceof Date && date2 instanceof Date) {
      return date1.getFullYear() <= date2.getFullYear() && date1.getMonth() < date2.getMonth();
    }
    return false;
  }

  /**
   * Checks if date1 is less than date2 based on only full date (YYYY-MM-DD)
   */
  isLessThanYYYYMMDD(date1: DateSource, date2: DateSource): boolean {
    const date1AsDayJs = dayjs(date1);
    const date2AsDayJs = dayjs(date2);

    return date1AsDayJs.isBefore(date2AsDayJs, "day");
  }

  isGreaterThanYYYYMM(date1: Date, date2: Date): boolean {
    if (date1 instanceof Date && date2 instanceof Date) {
      return date1.getFullYear() >= date2.getFullYear() && date1.getMonth() > date2.getMonth();
    }
    return false;
  }

  getNumericTimeFromDate(date: Date): number {
    if (!this.isDateValid(date)) {
      return null;
    }

    const hour = date.getHours();
    const hourWithZeros = ("0" + hour).slice(-2);
    const minutes = date.getMinutes();
    const minutesWithZeros = ("0" + minutes).slice(-2);

    const hourAndMintes = hourWithZeros + "" + minutesWithZeros;

    return parseInt(hourAndMintes);
  }

  isBefore(date1: DateSource, date2: DateSource): boolean {
    return dayjs(date1).isBefore(date2);
  }

  isAfter(date1: DateSource, date2: DateSource): boolean {
    return dayjs(date1).isAfter(date2);
  }

  compareDates(dateA: DateSource, dateB: DateSource) {
    if (this.isAfter(dateA, dateB)) {
      return 1;
    }

    if (this.isBefore(dateA, dateB)) {
      return -1;
    }
    return 0;
  }

  fullDaysBetweenDates(dateA: DateSource, dateB: DateSource): number {
    return Math.abs(dayjs(dateB).diff(dayjs(dateA), "day"));
  }

  getEarliestDate(dates: DateSource[]): DateSource | undefined {
    return dates.reduce<DateSource | undefined>(
      (earliest, current) => (!earliest || dayjs(current).isBefore(dayjs(earliest)) ? current : earliest),
      undefined,
    );
  }

  isDateValid(date: DateSource, format?: string): boolean {
    if (date) {
      return dayjs(date, format).isValid();
    }
    return false;
  }

  addMinutes(date: DateSource, minutes: number): Date {
    if (!this.isDateValid(date)) {
      return null;
    }

    const parsedDate = createDate(date);

    return createDate(parsedDate.getTime() + minutes * 60000);
  }

  getTimestamp(minutes) {
    const timeStampDate = this.addMinutes(createDate(), minutes);
    return timeStampDate.getTime();
  }

  getAge(birthDate) {
    if (!birthDate) {
      return null;
    }

    const yearInMilliseconds = 3.15576e10;
    return Math.floor((createDate().getTime() - createDate(birthDate).getTime()) / yearInMilliseconds);
  }

  /**
   * Wrapper around dayjs.duration
   * @argument time - the time number to create a duration from. E.g. 5
   * @argument unit - the unit of the time. E.g. "minutes"
   * @returns a dayjs duration object
   * */
  createDuration(time: number, unit?: duration.DurationUnitType) {
    return dayjs.duration(time, unit);
  }

  /** Changes the time (hours and minutes) of a date
   * @param {DateSource} date the date to change
   * @param {string} timeOfDay the time to set the date to, in the format "HH:mm"
   */
  dateWithModifiedTime(date: DateSource, timeOfDay: string): Date | undefined {
    const timeParts = timeOfDay.split(":");
    if (timeParts.length !== 2) {
      return undefined;
    }
    if (timeParts[0].length !== 2 || timeParts[1].length !== 2) {
      return undefined;
    }
    const hours = parseInt(timeParts[0]);
    const minutes = parseInt(timeParts[1]);
    if (hours < 0 || hours > 23 || minutes < 0 || minutes > 59) {
      return undefined;
    }
    const newDate = createDate(date);
    newDate.setHours(hours);
    newDate.setMinutes(minutes);
    return newDate;
  }

  /** Parses a "wall time" in the exact format of "2024-08-01T18:00"
   * and given a timezone like "Europe/Stockholm" and returns a date in UTC time like "2024-08-01T16:00:00Z" */

  parseWallDateTimeToUTCDateTime(dateTime: string | undefined, timezone: string) {
    const utcDateTime = this.wallTimeToUTCDateTime(dateTime, timezone);

    if (utcDateTime === undefined) {
      return undefined;
    }

    return utcDateTime.toISOString();
  }

  wallTimeToUTCDateTime(localDateTime: string, timezone: string): Date | undefined {
    if (!localDateTime) return undefined;

    const format = "YYYY-MM-DDTHH:mm";
    if (!dayjs(localDateTime, format, true).isValid()) return undefined;

    try {
      return dayjs.tz(localDateTime, format, timezone).utc().toDate();
    } catch (error) {
      return undefined;
    }
  }

  durationBetween(date1: DateSource, date2: DateSource, unit: QUnitType | OpUnitType): number {
    const dayjsDate1 = dayjs(date1);
    const dayjsDate2 = dayjs(date2);
    return dayjsDate1.diff(dayjsDate2, unit);
  }
}

const helper = new DateHelper();
export default helper;

/**
 * A function that creates a date with dayjs and converts it to Date object,
 * exists because older safari browsers otherwise create date to UTC when no timezone is specified
 * */
export const createDate = (dateInfo: DateSource = null, format?: string) => {
  if (dateInfo) {
    return dayjs(dateInfo, format).toDate();
  }

  return dayjs(TodayHelper.getNow()).toDate();
};
